// Rotativo sem planilha: a lista (quem está ligado, ordem, o nome que vai no
// "nome atendente" e quantos atendimentos por rodada) fica na memória deste
// fluxo. Liga/desliga na tela Rotativo do Setup da Conta. Esta é a lista de
// quando o fluxo foi gerado:
const INICIAL = ["__ORDEM_ROTATIVO__"];

const memoria = $getWorkflowStaticData('global');
const lista = Array.isArray(memoria.lista) ? memoria.lista : INICIAL;
const fila = lista.filter((p) => p.ligado && p.nome);
if (!fila.length) throw new Error('Ninguém ligado no rotativo: ligue alguém na tela Rotativo do Setup da Conta.');

// Rodízio com peso, intercalado (peso 2 = o dobro de atendimentos): a cada
// chamada soma o peso de cada um a um saldo, escolhe o maior saldo (empate: a
// ordem da lista) e desconta o total. O saldo fica na memória do fluxo (só com
// o fluxo ativo; no teste manual começa do primeiro).
const peso = (p) => Math.max(1, Math.min(10, Math.round(Number(p.peso) || 1)));
const total = fila.reduce((s, p) => s + peso(p), 0);
const saldo = memoria.saldo && typeof memoria.saldo === 'object' ? memoria.saldo : {};
for (const id of Object.keys(saldo)) if (!fila.some((p) => p.id === id)) delete saldo[id];
for (const p of fila) saldo[p.id] = (Number(saldo[p.id]) || 0) + peso(p);
const proximo = fila.reduce((melhor, p) => (saldo[p.id] > saldo[melhor.id] ? p : melhor), fila[0]);
saldo[proximo.id] -= total;
memoria.saldo = saldo;
memoria.ultimo = proximo.id;

// O que veio do chatbot (contato, conversa e contador) segue junto, para os
// próximos nós não dependerem do nome do nó de webhook.
const entrada = ($input.first().json || {}).body || {};
const contato = entrada.contact || {};
const qtdRotativo = (parseInt(entrada.metadata && entrada.metadata.qtdRotativo) || 0) + 1;

// Registro da conversa para o transbordo (também vai no metadata da conversa, pela resposta ao chatbot).
if (entrada.sessionId) {
  const registros = memoria.rotativo && typeof memoria.rotativo === 'object' ? memoria.rotativo : {};
  registros[entrada.sessionId] = { userId: proximo.id, em: new Date().toISOString(), rodadas: 0 };
  memoria.rotativo = registros;
}

return [{ json: {
  userId: proximo.id, nome: proximo.nome, posicao: fila.indexOf(proximo) + 1, total: fila.length,
  contactId: contato.id || null, sessionId: entrada.sessionId || null, qtdRotativo,
} }];

