// Usado pela tela Rotativo do Setup da Conta para ler e gravar a lista.
// Só responde com a chave certa (gerada para esta conta).
const CHAVE = "__ROTATIVO_CHAVE__";
const INICIAL = ["__ORDEM_ROTATIVO__"];

const body = $('Webhook config').first().json.body || {};
if (body.chave !== CHAVE) return [{ json: { ok: false, erro: 'chave inválida' } }];

const memoria = $getWorkflowStaticData('global');
if (!Array.isArray(memoria.lista)) memoria.lista = INICIAL;
if (body.acao === 'salvar' && Array.isArray(body.lista)) {
  memoria.lista = body.lista
    .filter((p) => p && typeof p.id === 'string')
    .map((p) => ({ id: p.id, nome: String(p.nome || '').slice(0, 100), ligado: Boolean(p.ligado), peso: Math.max(1, Math.min(10, Math.round(Number(p.peso) || 1))) }));
}
// Transbordo: { ligado, minutos } (a tela só manda quando o fluxo tem transbordo).
if (body.acao === 'salvar' && body.transbordo && typeof body.transbordo === 'object') {
  const m = Number(body.transbordo.minutos) || Number(body.transbordo.horas) * 60;
  memoria.transbordo = { ligado: Boolean(body.transbordo.ligado), minutos: m > 0 ? Math.min(Math.max(Math.round(m), 1), 10080) : 180, criterio: body.transbordo.criterio === 'assumiu' ? 'assumiu' : 'resposta', soHorario: body.transbordo.soHorario !== false };
}
return [{ json: { ok: true, lista: memoria.lista, ultimo: memoria.ultimo || null, versao: 3, transbordo: memoria.transbordo || { ligado: false, minutos: 180, criterio: 'resposta', soHorario: true } } }];

// Transbordo do rotativo: ligar/desligar, o tempo (em minutos) e o critério de
// "atendida" vêm da tela Rotativo do Setup da Conta.
const memoria = $getWorkflowStaticData('global');
const t = memoria.transbordo || {};
if (!t.ligado) return [];
const minutos = Number(t.minutos) > 0 ? Number(t.minutos) : Number(t.horas) > 0 ? Number(t.horas) * 60 : 180;
// 'resposta' = o atendente mandou mensagem; 'assumiu' = a conversa está com alguém.
const criterio = t.criterio === 'assumiu' ? 'assumiu' : 'resposta';
// Só trocar dentro do horário de atendimento da conta (padrão: sim).
const soHorario = t.soHorario !== false;
return [{ json: { minutos, criterio, soHorario } }];

// Transbordo: conversas que o rotativo distribuiu, sem atendimento há mais tempo
// que o configurado → vão para a próxima pessoa ligada da lista (na equipe com o
// nome dela, como o chatbot faz). Só roda dentro do horário de atendimento.
// Quando não há o que fazer, devolve um item com o motivo (aparece na execução).
const INICIAL = ["__ORDEM_ROTATIVO__"];
const memoria = $getWorkflowStaticData('global');
const { minutos, criterio, soHorario } = $('Transbordo ligado?').first().json;
const lista = Array.isArray(memoria.lista) ? memoria.lista : INICIAL;
const fila = lista.filter((p) => p.ligado && p.nome);
const motivo = (texto, extra) => [{ json: { motivo: texto, ...(extra || {}) } }];
if (fila.length < 2) return motivo('Menos de 2 pessoas ligadas no rotativo: não há para quem passar', { ligadas: fila.length });

// Horário de atendimento da conta (dias como MONDAY..SUNDAY ou 0..6, 0 = domingo).
const oh = $('Horário de atendimento').first().json || {};
if (soHorario !== false && oh.limitHours && Array.isArray(oh.days) && oh.days.length) {
  let diff = Number.isFinite(Number(oh.timezoneDiff)) ? Number(oh.timezoneDiff) : -3;
  if (Math.abs(diff) > 14) diff = diff / 60; // veio em minutos
  const local = new Date(Date.now() + diff * 3600000);
  const NOMES = ['SUNDAY', 'MONDAY', 'TUESDAY', 'WEDNESDAY', 'THURSDAY', 'FRIDAY', 'SATURDAY'];
  const d = local.getUTCDay();
  const dia = oh.days.find((x) => { const k = String(x.dayWeek ?? '').toUpperCase(); return k === NOMES[d] || k === String(d); });
  const hm = local.toISOString().slice(11, 16);
  const aberto = !dia || (dia.active !== false && (dia.periods || []).some((p) => String(p.startTime).slice(0, 5) <= hm && hm < String(p.endTime).slice(0, 5)));
  if (!aberto) return motivo('Fora do horário de atendimento (' + NOMES[d] + ' ' + hm + ' no fuso da conta)', { dia: NOMES[d], hora: hm });
}

const agora = Date.now();
// Conversas distribuídas pelo rotativo: memória do fluxo (gravada ao distribuir e ao
// transbordar) e, como reserva, o metadata da conversa. Registros com mais de 7 dias saem.
const registros = memoria.rotativo && typeof memoria.rotativo === 'object' ? memoria.rotativo : {};
for (const [id, r] of Object.entries(registros)) if (!r || !r.em || agora - Date.parse(r.em) > 7 * 86400000) delete registros[id];
memoria.rotativo = registros;

const sessoes = $('Conversas abertas').first().json.items || [];
const equipes = $('Equipes').first().json.body || [];
const norm = (s) => String(s || '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').trim().replace(/\s+/g, ' ').toLowerCase();
const equipePorNome = new Map(equipes.map((e) => [norm(e.name), e.id]));
const ids = fila.map((p) => p.id);
const out = [];
let doRotativo = 0, comAtendente = 0, recentes = 0;
for (const s of sessoes) {
  const m = s.metadata || {};
  const reg = registros[s.id];
  const emStr = (reg && reg.em) || m.rotativoEm;
  if (!emStr) continue; // não veio do rotativo
  doRotativo += 1;
  if (criterio === 'assumiu' && s.userId) { comAtendente += 1; continue; } // alguém já assumiu
  const em = Date.parse(emStr);
  if (!em || agora - em < minutos * 60000) { recentes += 1; continue; }
  const atualId = (reg && reg.userId) || m.rotativoUserId;
  const proximo = fila[(ids.indexOf(atualId) + 1) % fila.length];
  if (!proximo || proximo.id === atualId) continue;
  const rodadas = (reg && Number(reg.rodadas)) || Number(m.rotativoRodadas) || 0;
  out.push({ json: {
    sessionId: s.id, contactId: s.contactId, companyId: s.companyId || null, userId: proximo.id, nome: proximo.nome,
    equipeId: equipePorNome.get(norm(proximo.nome)) || null,
    rodadas: rodadas + 1, em: new Date(agora).toISOString(), criterio,
  } });
}
if (out.length) return out;
if (!doRotativo) return motivo('Nenhuma das ' + sessoes.length + ' conversa(s) aberta(s) veio do rotativo', { abertas: sessoes.length });
if (comAtendente === doRotativo) return motivo(doRotativo + ' conversa(s) do rotativo, todas já com atendente (critério: alguém assumir)', { doRotativo, comAtendente });
return motivo(doRotativo + ' conversa(s) do rotativo, nenhuma parada há ' + minutos + ' min', { doRotativo, recentes });

// Critério "o atendente respondeu": confere nas mensagens de cada conversa
// candidata se uma pessoa já respondeu (mensagem enviada por usuário, não por
// chatbot, API ou mensagem automática). Quem já teve resposta sai do transbordo.
const memoria = $getWorkflowStaticData('global');
const candidatas = $('Quem transborda').all();
const respostas = $input.all();
const out = [];
candidatas.forEach((c, i) => {
  const cand = c.json;
  if (cand.criterio === 'assumiu') { out.push({ json: cand, pairedItem: { item: i } }); return; }
  const r = respostas[i] && respostas[i].json ? respostas[i].json : {};
  if (r.error) return; // não conseguiu ler as mensagens: não mexe nesta conversa
  const msgs = Array.isArray(r.items) ? r.items : Array.isArray(r) ? r : [];
  const respondeu = msgs.some((m) => m.direction === 'FROM_HUB' && m.userId && (m.origin || 'DEFAULT') === 'DEFAULT' && !['TRANSITION', 'TRACK', 'NOTE'].includes(m.type));
  if (!respondeu) out.push({ json: cand, pairedItem: { item: i } });
});
// Registra na memória do fluxo quem recebe agora (a transferência vem em seguida).
const registros = memoria.rotativo && typeof memoria.rotativo === 'object' ? memoria.rotativo : {};
for (const i of out) registros[i.json.sessionId] = { userId: i.json.userId, em: i.json.em, rodadas: i.json.rodadas };
memoria.rotativo = registros;
return out;
